ValidationRule.errorConditionFormula:
AND( Integration__c = false, Marketing_Lead__c = false, Case_Accounts__c =false, Person_Account__c =false, ISPICKVAL(BillCountry__c,"India"), ISPICKVAL(PostCountry__c ,"India"),
OR(NOT(REGEX(BillingPostalCode,"\\d{6}")),NOT(REGEX(ShippingPostalCode,"\\d{6}")))
)
